const body = $json.body || $json;
const required = ['run_id','account_id','website_url'];
const missing = required.filter(key => body[key] === undefined || body[key] === null || String(body[key]).trim() === '');
if (missing.length) throw new Error(`Missing required fields: ${missing.join(', ')}`);
const expected = $vars.N8N_WEBHOOK_SECRET;
const supplied = $json.headers?.['x-workflow-secret'];
if (!expected || supplied !== expected) throw new Error('Invalid workflow secret');
const rawWebsite = String(body.website_url).trim().replace(/^[\"'“”‘’]+|[\"'“”‘’]+$/g, '');
const declaredScheme = rawWebsite.match(/^([a-z][a-z0-9+.-]*):/i)?.[1]?.toLowerCase();
if (declaredScheme && !['http','https'].includes(declaredScheme)) throw new Error('Unsupported URL scheme');
const candidate = declaredScheme ? rawWebsite : `https://${rawWebsite.replace(/^\/\//, '')}`;
if (/\s/.test(candidate)) throw new Error('website_url cannot contain spaces');
const parsed = candidate.match(/^(https?):\/\/([^\/?#]+)([^?#]*)(?:\?([^#]*))?(?:#.*)?$/i);
if (!parsed) throw new Error(`website_url could not be parsed: ${rawWebsite}`);
const protocol = parsed[1].toLowerCase();
const authority = parsed[2];
if (authority.includes('@')) throw new Error('Credentials are not allowed in website_url');
const authorityParts = authority.split(':');
if (authorityParts.length > 2) throw new Error('Invalid website host');
const rawHost = authorityParts[0].toLowerCase().replace(/\.$/, '');
const port = authorityParts[1] || '';
if (port && !/^\d{1,5}$/.test(port)) throw new Error('Invalid website port');
const domain = rawHost.replace(/^www\./, '');
const domainPattern = /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i;
if (!domainPattern.test(domain)) throw new Error(`Invalid canonical domain: ${domain}`);
const pathname = parsed[3] || '/';
const queryParts = (parsed[4] || '').split('&').filter(Boolean).filter(part => {
  const encodedKey = part.split('=', 1)[0].replace(/\+/g, ' ');
  let key = encodedKey;
  try { key = decodeURIComponent(encodedKey); } catch {}
  return !/^(utm_|gclid|fbclid)/i.test(key);
});
const query = queryParts.length ? `?${queryParts.join('&')}` : '';
const portSuffix = port ? `:${port}` : '';
const websiteUrl = `${protocol}://${domain}${portSuffix}${pathname}${query}`;
return [{json:{...body,website_url:websiteUrl,domain,workflow_version:'wf01-v3',received_at:new Date().toISOString()}}];

const intake = $('Validate & Canonicalize').first().json;
const failed = Boolean($json.error || Number($json.statusCode) >= 400);
const errorValue = $json.message || $json.error || null;
const errorMessage = typeof errorValue === 'string' ? errorValue : errorValue ? JSON.stringify(errorValue) : 'WF02 request failed';
return [{json:{run_id:intake.run_id,account_id:intake.account_id,status:failed?'failed_partial':'researching',next_workflow:'WF02',error:failed?errorMessage:null}}];
